    def _UnPack(self, FSO):
        if FSO is None:
            return
        self.OPERATION = FSO.OPERATION()
        self.REQUEST_ID = FSO.REQUEST_ID()
        self.DATABASE_NAME = FSO.DATABASE_NAME()
        if not FSO.SCHEMA_IDLIsNone():
            if np is None:
                self.SCHEMA_IDL = []
                for i in range(FSO.SCHEMA_IDLLength()):
                    self.SCHEMA_IDL.append(FSO.SCHEMA_IDL(i))
            else:
                self.SCHEMA_IDL = FSO.SCHEMA_IDLAsNumpy()
        if not FSO.TABLE_BINDINGSIsNone():
            self.TABLE_BINDINGS = []
            for i in range(FSO.TABLE_BINDINGSLength()):
                if FSO.TABLE_BINDINGS(i) is None:
                    self.TABLE_BINDINGS.append(None)
                else:
                    fSOTableBinding_ = FSOTableBinding.FSOTableBindingT.InitFromObj(FSO.TABLE_BINDINGS(i))
                    self.TABLE_BINDINGS.append(fSOTableBinding_)
        self.TABLE_NAME = FSO.TABLE_NAME()
        self.INDEX_NAME = FSO.INDEX_NAME()
        if not FSO.INDEX_EXPRESSIONIsNone():
            if np is None:
                self.INDEX_EXPRESSION = []
                for i in range(FSO.INDEX_EXPRESSIONLength()):
                    self.INDEX_EXPRESSION.append(FSO.INDEX_EXPRESSION(i))
            else:
                self.INDEX_EXPRESSION = FSO.INDEX_EXPRESSIONAsNumpy()
        self.VIEW_NAME = FSO.VIEW_NAME()
        if not FSO.QUERYIsNone():
            if np is None:
                self.QUERY = []
                for i in range(FSO.QUERYLength()):
                    self.QUERY.append(FSO.QUERY(i))
            else:
                self.QUERY = FSO.QUERYAsNumpy()
        if not FSO.PARAMETERSIsNone():
            if np is None:
                self.PARAMETERS = []
                for i in range(FSO.PARAMETERSLength()):
                    self.PARAMETERS.append(FSO.PARAMETERS(i))
            else:
                self.PARAMETERS = FSO.PARAMETERSAsNumpy()
        self.PARAMETER_COUNT = FSO.PARAMETER_COUNT()
        if not FSO.UPSERT_KEY_EXPRESSIONIsNone():
            if np is None:
                self.UPSERT_KEY_EXPRESSION = []
                for i in range(FSO.UPSERT_KEY_EXPRESSIONLength()):
                    self.UPSERT_KEY_EXPRESSION.append(FSO.UPSERT_KEY_EXPRESSION(i))
            else:
                self.UPSERT_KEY_EXPRESSION = FSO.UPSERT_KEY_EXPRESSIONAsNumpy()
        self.RETENTION_MAX_RECORDS = FSO.RETENTION_MAX_RECORDS()
        self.RETENTION_MAX_AGE_MILLIS = FSO.RETENTION_MAX_AGE_MILLIS()
        self.COMPACTION_TARGET_BYTES = FSO.COMPACTION_TARGET_BYTES()
        self.STATUS = FSO.STATUS()
        self.AFFECTED_RECORDS = FSO.AFFECTED_RECORDS()
        self.RESULT_BYTES = FSO.RESULT_BYTES()
        self.ERROR_CODE = FSO.ERROR_CODE()
        if not FSO.MESSAGEIsNone():
            if np is None:
                self.MESSAGE = []
                for i in range(FSO.MESSAGELength()):
                    self.MESSAGE.append(FSO.MESSAGE(i))
            else:
                self.MESSAGE = FSO.MESSAGEAsNumpy()

    # FSOT
    def Pack(self, builder):
        if self.DATABASE_NAME is not None:
            DATABASE_NAME = builder.CreateString(self.DATABASE_NAME)
        if self.SCHEMA_IDL is not None:
            if np is not None and type(self.SCHEMA_IDL) is np.ndarray:
                SCHEMA_IDL = builder.CreateNumpyVector(self.SCHEMA_IDL)
            else:
                FSOStartSCHEMA_IDLVector(builder, len(self.SCHEMA_IDL))
                for i in reversed(range(len(self.SCHEMA_IDL))):
                    builder.PrependUint8(self.SCHEMA_IDL[i])
                SCHEMA_IDL = builder.EndVector()
        if self.TABLE_BINDINGS is not None:
            TABLE_BINDINGSlist = []
            for i in range(len(self.TABLE_BINDINGS)):
                TABLE_BINDINGSlist.append(self.TABLE_BINDINGS[i].Pack(builder))
            FSOStartTABLE_BINDINGSVector(builder, len(self.TABLE_BINDINGS))
            for i in reversed(range(len(self.TABLE_BINDINGS))):
                builder.PrependUOffsetTRelative(TABLE_BINDINGSlist[i])
            TABLE_BINDINGS = builder.EndVector()
        if self.TABLE_NAME is not None:
            TABLE_NAME = builder.CreateString(self.TABLE_NAME)
        if self.INDEX_NAME is not None:
            INDEX_NAME = builder.CreateString(self.INDEX_NAME)
        if self.INDEX_EXPRESSION is not None:
            if np is not None and type(self.INDEX_EXPRESSION) is np.ndarray:
                INDEX_EXPRESSION = builder.CreateNumpyVector(self.INDEX_EXPRESSION)
            else:
                FSOStartINDEX_EXPRESSIONVector(builder, len(self.INDEX_EXPRESSION))
                for i in reversed(range(len(self.INDEX_EXPRESSION))):
                    builder.PrependUint8(self.INDEX_EXPRESSION[i])
                INDEX_EXPRESSION = builder.EndVector()
        if self.VIEW_NAME is not None:
            VIEW_NAME = builder.CreateString(self.VIEW_NAME)
        if self.QUERY is not None:
            if np is not None and type(self.QUERY) is np.ndarray:
                QUERY = builder.CreateNumpyVector(self.QUERY)
            else:
                FSOStartQUERYVector(builder, len(self.QUERY))
                for i in reversed(range(len(self.QUERY))):
                    builder.PrependUint8(self.QUERY[i])
                QUERY = builder.EndVector()
        if self.PARAMETERS is not None:
            if np is not None and type(self.PARAMETERS) is np.ndarray:
                PARAMETERS = builder.CreateNumpyVector(self.PARAMETERS)
            else:
                FSOStartPARAMETERSVector(builder, len(self.PARAMETERS))
                for i in reversed(range(len(self.PARAMETERS))):
                    builder.PrependUint8(self.PARAMETERS[i])
                PARAMETERS = builder.EndVector()
        if self.UPSERT_KEY_EXPRESSION is not None:
            if np is not None and type(self.UPSERT_KEY_EXPRESSION) is np.ndarray:
                UPSERT_KEY_EXPRESSION = builder.CreateNumpyVector(self.UPSERT_KEY_EXPRESSION)
            else:
                FSOStartUPSERT_KEY_EXPRESSIONVector(builder, len(self.UPSERT_KEY_EXPRESSION))
                for i in reversed(range(len(self.UPSERT_KEY_EXPRESSION))):
                    builder.PrependUint8(self.UPSERT_KEY_EXPRESSION[i])
                UPSERT_KEY_EXPRESSION = builder.EndVector()
        if self.ERROR_CODE is not None:
            ERROR_CODE = builder.CreateString(self.ERROR_CODE)
        if self.MESSAGE is not None:
            if np is not None and type(self.MESSAGE) is np.ndarray:
                MESSAGE = builder.CreateNumpyVector(self.MESSAGE)
            else:
                FSOStartMESSAGEVector(builder, len(self.MESSAGE))
                for i in reversed(range(len(self.MESSAGE))):
                    builder.PrependUint8(self.MESSAGE[i])
                MESSAGE = builder.EndVector()
        FSOStart(builder)
        FSOAddOPERATION(builder, self.OPERATION)
        FSOAddREQUEST_ID(builder, self.REQUEST_ID)
        if self.DATABASE_NAME is not None:
            FSOAddDATABASE_NAME(builder, DATABASE_NAME)
        if self.SCHEMA_IDL is not None:
            FSOAddSCHEMA_IDL(builder, SCHEMA_IDL)
        if self.TABLE_BINDINGS is not None:
            FSOAddTABLE_BINDINGS(builder, TABLE_BINDINGS)
        if self.TABLE_NAME is not None:
            FSOAddTABLE_NAME(builder, TABLE_NAME)
        if self.INDEX_NAME is not None:
            FSOAddINDEX_NAME(builder, INDEX_NAME)
        if self.INDEX_EXPRESSION is not None:
            FSOAddINDEX_EXPRESSION(builder, INDEX_EXPRESSION)
        if self.VIEW_NAME is not None:
            FSOAddVIEW_NAME(builder, VIEW_NAME)
        if self.QUERY is not None:
            FSOAddQUERY(builder, QUERY)
        if self.PARAMETERS is not None:
            FSOAddPARAMETERS(builder, PARAMETERS)
        FSOAddPARAMETER_COUNT(builder, self.PARAMETER_COUNT)
        if self.UPSERT_KEY_EXPRESSION is not None:
            FSOAddUPSERT_KEY_EXPRESSION(builder, UPSERT_KEY_EXPRESSION)
        FSOAddRETENTION_MAX_RECORDS(builder, self.RETENTION_MAX_RECORDS)
        FSOAddRETENTION_MAX_AGE_MILLIS(builder, self.RETENTION_MAX_AGE_MILLIS)
        FSOAddCOMPACTION_TARGET_BYTES(builder, self.COMPACTION_TARGET_BYTES)
        FSOAddSTATUS(builder, self.STATUS)
        FSOAddAFFECTED_RECORDS(builder, self.AFFECTED_RECORDS)
        FSOAddRESULT_BYTES(builder, self.RESULT_BYTES)
        if self.ERROR_CODE is not None:
            FSOAddERROR_CODE(builder, ERROR_CODE)
        if self.MESSAGE is not None:
            FSOAddMESSAGE(builder, MESSAGE)
        FSO = FSOEnd(builder)
        return FSO
